int main(){std::cout<<std::setprecision(17);int cases;if(!(std::cin>>cases))return 2;for(int row=0;row<cases;row++){int kind,iterations;Real dt,compliance,restValue;std::cin>>kind>>iterations>>dt>>compliance>>restValue;int n=kind==0?2:4;std::array<Vector3r,4> rest,p;Real mass[4];for(int i=0;i<n;i++)for(int k=0;k<3;k++)std::cin>>rest[i].v[k];for(int i=0;i<n;i++)for(int k=0;k<3;k++)std::cin>>p[i].v[k];for(int i=0;i<n;i++)std::cin>>mass[i];Real stiffness=compliance==0?0:1/compliance,lambda=0;Matrix4r q;if(kind==1)XPBD::init_IsometricBendingConstraint(rest[0],rest[1],rest[2],rest[3],q);int rejected=0;for(int j=0;j<iterations;j++){std::array<Vector3r,4> c;bool ok=kind==0?XPBD::solve_DistanceConstraint(p[0],mass[0],p[1],mass[1],restValue,stiffness,dt,lambda,c[0],c[1]):kind==1?XPBD::solve_IsometricBendingConstraint(p[0],mass[0],p[1],mass[1],p[2],mass[2],p[3],mass[3],q,stiffness,dt,lambda,c[0],c[1],c[2],c[3]):XPBD::solve_VolumeConstraint(p[0],mass[0],p[1],mass[1],p[2],mass[2],p[3],mass[3],restValue,stiffness,dt,lambda,c[0],c[1],c[2],c[3]);rejected+=!ok;for(int i=0;i<n;i++)p[i]+=c[i];}std::cout<<n<<' '<<lambda<<' '<<rejected;for(int i=0;i<n;i++)for(int k=0;k<3;k++)std::cout<<' '<<p[i].v[k];std::cout<<'\n';}return std::cin.fail()?3:0;}
